/text2image/image-synthesis\": dashscope.aliyuncs.com',_binary '\0',NULL,'{}',NULL,NULL,'1','2025-11-15 12:02:30','1','2025-11-15 12:02:30',_binary '\0',1),(201,1,'中国旗袍','OpenAI',35,'dall-e-3',1024,1024,30,'2025-11-15 12:02:43','I/O error on POST request for \"https://api.holdai.top/v1/images/generations\": api.holdai.top: nodename nor servname provided, or not known',_binary '\0',NULL,'{\"style\": \"vivid\"}',NULL,NULL,'1','2025-11-15 12:02:43','1','2025-11-15 12:02:43',_binary '\0',1),(203,1,'xxx','StableDiffusion',37,'stable-diffusion-v1-6',512,512,30,'2025-11-15 12:02:59','I/O error on POST request for \"https://api.stability.ai/v1/generation/stable-diffusion-v1-6/text-to-image\": api.stability.ai: nodename nor servname provided, or not known',_binary '\0',NULL,'{\"seed\": \"42\", \"scale\": \"7.5\", \"steps\": \"20\", \"sampler\": \"DDIM\", \"stylePreset\": \"3d-model\", \"clipGuidancePreset\": \"NONE\"}',NULL,NULL,'1','2025-11-15 12:02:59','1','2025-11-15 12:02:59',_binary '\0',1),(204,1,'1','TongYi',31,'wanx-v1',512,512,30,'2025-11-15 14:29:27','400 - {\"code\":\"Arrearage\",\"message\":\"Access denied, please make sure your account is in good standing. For details, see: https://help.aliyun.com/zh/model-studio/error-code#overdue-payment\",\"request_id\":\"187e4f42-a4ff-4f32-bfe0-3fa59a3b156d\"}',_binary '\0',NULL,'{}',NULL,NULL,'1','2025-11-15 14:29:27','1','2025-11-15 14:29:27',_binary '\0',1),(205,1,'3231221','OpenAI',35,'dall-e-3',1024,1024,30,'2025-11-15 15:16:57','401 - {\"error\":{\"code\":\"invalid_request\",\"message\":\"[sk-Pyt***mpD] 该令牌额度已用尽，余额：[$-1.010144] (request id: B20251115151656657052024FvQBgFLT)\",\"type\":\"new_api_error\"}}',_binary '\0',NULL,'{\"style\": \"vivid\"}',NULL,NULL,'1','2025-11-15 15:16:56','1','2025-11-15 15:16:57',_binary '\0',1),(206,1,'3231221','OpenAI',35,'dall-e-3',1024,1024,30,'2025-11-15 15:17:06','401 - {\"error\":{\"code\":\"invalid_request\",\"message\":\"[sk-Pyt***mpD] 该令牌额度已用尽，余额：[$-1.010144] (request id: B20251115151705543817050JCgqS7t9)\",\"type\":\"new_api_error\"}}',_binary '\0',NULL,'{\"style\": \"vivid\"}',NULL,NULL,'1','2025-11-15 15:17:05','1','2025-11-15 15:17:06',_binary '\0',1);
