INSERT INTO `ai_mind_map` VALUES (1,1,'32132312',NULL,'OpenAI',0,'gpt-3.5-turbo','403 Forbidden from POST https://api.holdai.top/v1/chat/completions','1','2024-07-29 21:43:30',NULL,'2024-08-10 09:27:48',_binary '',1),(2,1,'vue 技术栈！','# Vue 技术栈\n## 核心框架\n### Vue.js\n### Vue Router\n### Vuex\n## 构建工具\n### Webpack\n### Vite\n## UI 框架\n### Element UI\n### Vuetify\n### Ant Design Vue\n## 状态管理\n### Pinia\n### Vuex\n## 测试工具\n### Vue Test Utils\n### Jest\n## 服务器端渲染\n### Nuxt.js\n## 静态站点生成\n### VuePress\n### VitePress','DeepSeek',0,'deepseek-chat',NULL,'1','2024-07-29 21:48:11',NULL,'2024-07-29 21:48:18',_binary '\0',1),(3,1,'生成一个 Vue 核心关键点','# Vue 核心关键点\n## 数据绑定\n### 单向数据绑定\n### 双向数据绑定\n## 组件系统\n### 组件定义\n### 组件通信\n#### 父子组件通信\n#### 非父子组件通信\n## 生命周期钩子\n### 创建阶段\n### 挂载阶段\n### 更新阶段\n### 销毁阶段\n## 指令\n### v-bind\n### v-model\n### v-on\n### v-for\n### v-if\n## 计算属性和侦听器\n### 计算属性\n### 侦听器\n## 插槽\n### 默认插槽\n### 具名插槽\n### 作用域插槽\n## 路由\n### Vue Router\n### 路由配置\n### 路由导航\n## 状态管理\n### Vuex\n### 状态\n###  mutations\n###  actions\n###  getters','DeepSeek',0,'deepseek-chat',NULL,'1','2024-07-29 21:56:45',NULL,'2024-07-29 21:56:56',_binary '\0',1),(4,1,'vue 学习路线',NULL,'OpenAI',11,'gpt-4.1-nano','Connection refused: api.holdai.top/198.18.5.234:443','1','2025-10-26 14:53:30','1','2025-10-26 14:53:38',_binary '\0',1),(5,1,'测试一下','# 测试\n## 功能验证\n### 系统响应\n#### 输入处理\n#### 输出生成\n## 性能评估\n### 处理速度\n### 准确性\n## 用户体验\n### 界面交互\n### 反馈机制','DeepSeek',17,'deepseek-chat',NULL,'1','2025-10-26 14:58:32','1','2025-10-26 14:58:35',_binary '\0',1),(6,1,'测试','# 测试','DeepSeek',17,'deepseek-chat',NULL,'1','2025-10-26 14:58:45','1','2025-10-26 14:58:47',_binary '\0',1),(7,1,'测试','# 测试','DeepSeek',17,'deepseek-chat',NULL,'1','2025-10-26 14:58:52','1','2025-10-26 14:58:53',_binary '\0',1),(8,1,'生成下路线，java 的','# Java学习路线\n## 编程基础\n### 计算机基础\n#### 操作系统原理\n#### 计算机网络\n#### 数据结构与算法\n### Java基础语法\n#### 数据类型与变量\n#### 流程控制语句\n#### 面向对象编程\n#### 异常处理机制\n## 核心技术\n### Java集合框架\n#### List集合\n#### Set集合\n#### Map集合\n### I