  KEY `idx_payment_id` (`payment_id`) USING BTREE,
  KEY `idx_biz_no` (`biz_no`) USING BTREE,
  KEY `idx_biz_id_biz_type` (`biz_id`,`biz_type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5020 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ERP 付款项表';
