--
-- Table structure for table `fms_closing`
--

DROP TABLE IF EXISTS `fms_closing`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fms_closing` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结账名称',
  `period_end` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否期末结转',
  `subject_id` bigint DEFAULT NULL COMMENT '科目编号',
  `formula_rule` int DEFAULT NULL COMMENT '取数规则',
  `time_type` int DEFAULT NULL COMMENT '取数时间类型',
  `voucher_word_id` bigint DEFAULT NULL COMMENT '凭证字编号',
  `digest` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '凭证摘要',
  `voucher_type` int DEFAULT NULL COMMENT '结转凭证类型',
  `prior_year_adjustment_subject_id` bigint DEFAULT NULL COMMENT '“以前年度损益调整”科目',
  `adjustment_closing_subject_id` bigint DEFAULT NULL COMMENT '“以前年度损益调整”科目的结转科目',
  `other_closing_subject_id` bigint DEFAULT NULL COMMENT '其他损益科目的结转科目',
  `reverse_balance` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否按余额反向结转',
  `type` int DEFAULT NULL COMMENT '类型',
  `account_set_id` bigint DEFAULT NULL COMMENT '账套编号',
  `closing_day` int DEFAULT NULL COMMENT '结转损益日期，最大31，超过31默认最后一天',
  `subject_rules` json DEFAULT NULL COMMENT '结转科目规则数组',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_subject_id` (`subject_id`) USING BTREE,
