--
-- Table structure for table `fms_income_statement_report`
--

DROP TABLE IF EXISTS `fms_income_statement_report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fms_income_statement_report` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `type` int DEFAULT NULL COMMENT '类型',
  `from_period` int DEFAULT NULL COMMENT '开始会计期间，格式为 yyyyMM',
  `to_period` int DEFAULT NULL COMMENT '结束会计期间，格式为 yyyyMM',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置名称',
  `row_no` int DEFAULT NULL COMMENT '行次',
  `formula` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '公式',
  `sort` int DEFAULT NULL COMMENT '显示顺序',
  `editable` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否可编辑',
  `current_amount` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '本期金额',
  `year_amount` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '本年累计金额',
  `account_set_id` bigint DEFAULT NULL COMMENT '账套编号',
  `level` int DEFAULT NULL COMMENT '层级',
  `settled` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否已结账',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_account_set_id` (`account_set_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=373 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FMS 利润表数据';
/*!40101 SET character_set_client = @saved_cs_client */;

