INSERT INTO `hrm_personal_resume_version` VALUES (1,81059,NULL,1,62,NULL,1,'手动固化 2026/9/18 14:40:11','v1','{\"name\":\"王磊\",\"birthMonth\":\"2000-01\",\"mobile\":\"18236958739\",\"email\":\"c858967@gmail.com\",\"identity\":\"worker\",\"employmentStatus\":\"在职-考虑机会\",\"domicile\":\"陕西省 / 延安市 / 宝塔区\",\"strengths\":\"5年防腐保温工程经验，熟悉施工组织、质量验收与现场协调，能够独立推进项目从开工到交付。\",\"jobType\":\"fulltime\",\"expectedPostName\":\"防腐工\",\"industry\":\"防腐保温\",\"salary\":\"10k-20k\",\"expectedCities\":[\"陕西省\"],\"experiences\":[{\"id\":\"1789527728128-1zycmx\",\"company\":\"陕西防腐工程有限公司\",\"industry\":\"防腐保温\",\"department\":\"\",\"position\":\"防腐工\",\"start\":\"2021-08\",\"end\":\"2025-09\",\"description\":\"1. 负责钢结构、设备管道、储罐、混凝土构筑物的除锈、防腐、涂装全套施工工作，熟练掌握手工除锈、动力除锈、喷砂除锈等多种除锈工艺，严格把控除锈等级，确保基材表面符合防腐施工标准。\\n2. 按照施工方案和技术交底，规范完成环氧底漆、中间漆、面漆、玻璃钢防腐、沥青防腐、聚脲防腐等各类防腐涂料的配比与涂刷、喷涂作业，把控涂层厚度、均匀度，杜绝流挂、漏涂、气泡等质量问题。\\n3. 负责施工前期基层清理、打磨、除尘、干燥处理，施工后期成品保护、养护工作，及时处理施工中出现的起皮、脱落、开裂等防腐质量隐患。\\n4. 严格遵守施工现场安全管理制度，规范佩戴防护用具，做好高空作业、动火作业、有限空间作业的安全防护，配合安全员完成现场安全检查，全程零安全事故。\\n5. 配合项目技术员、质检员完成工程自检、复检工作，整理施工台账，如实记录施工工序、用料、施工时长等信息，确保工程顺利验收交付。\",\"achievements\":\"从业以来参与十余项工业、建筑防腐工程，施工合格率100%，交付项目均通过甲方及监理验收，无质量返修、安全事故记录，熟练适配各类场地、各类基材的防腐施工需求。\"}],\"projects\":[{\"id\":\"1789527916697-e80nmh\",\"name\":\"工业园区钢结构厂房整体防腐翻新项目\",\"role\":\"项目负责人\",\"link\":\"\",\"start\":\"2021-08\",\"end\":\"2023-06\",\"description\":\"该项目为老旧厂房翻新工程，钢结构存在大面积锈蚀、涂层脱落、风化老化问题。进场后首先采用角磨机、钢丝刷、喷砂设备对钢结构表面彻底除锈，清除氧化皮、铁锈、旧涂层及油污，将除锈等级控制在Sa2.5级；随后按工艺要求涂刷环氧富锌底漆、环氧云铁中间漆、丙烯酸聚氨酯面漆，分层把控涂层厚度，整体涂层厚度达标80-120μm；对钢结构接缝、边角、易腐蚀重点部位进行加厚涂刷处理，强化防腐效果；施工全程做好雨天、粉尘防护，完工后做好成品养护\",\"achievements\":\"高效完成近8000㎡钢结构防腐施工，施工质量符合《钢结构工程施工质量验收标准》，一次性通过监理及甲方验收，翻新后钢结构防腐使用寿命大幅提升，获得项目方认可。\",\"highlight\":true},{\"id\":\"1789527987793-568uxn\",\"name\":\"化工厂区管道及设备防腐防渗项目\",\"role\":\"项目负责人\",\"link\":\"\",\"start\":\"2023-11\",\"end\":\"2026-06\",\"description\":\"针对化工厂区酸碱腐蚀、湿气重的特殊工况，定制适配防腐施工方案。对碳钢管道、大型储罐外壁进行机械除锈、除尘干燥处理，采用环氧耐酸碱防腐涂料进行多层喷涂施工；对设备接口、管道焊缝、法兰等易渗漏、易腐蚀关键点位进行精细化打磨和加厚防腐处理；部分区域采用玻璃钢衬里防腐工艺，强化防渗、防腐蚀性能；严格把控涂料配比、施工温度、干燥时间，规避化工场地施工风险，全程落实安全施工规范。\",\"achievements\":\"完成厂区3000余米管道、10余台大型设备的防腐防渗施工，工程无渗漏、无腐蚀隐患，完美适配化工恶劣工况，顺利通过竣工验收，保障厂区设备长期稳定运行。\",\"highlight\":false}],\"educationExperiences\":[{\"id\":\"1789527728128-3izo9n\",\"degree\":\"大专\",\"school\":\"延安职业技术学校\",\"major\":\"建筑防腐与防水工程技术\",\"schoolType\":\"全日制\",\"start\":\"2018-09\",\"end\":\"2021-07\",\"experience\":\"在校担任学生会部长，获得校级奖学金，主修课程包括.防腐工程施工技术、金属防腐蚀原理、涂料施工工艺、钢结构除锈防腐、防水防渗施工、工程质量验收规范、安全施工操作规程\"}],\"skills\":\"1. 除锈工艺：熟练掌握手工除锈、动力工具除锈、喷砂除锈等全套除锈工艺，精准把控Sa2.0、Sa2.5、Sa3.0等各类除锈标准，可根据基材工况选择适配除锈方式。\\n2. 防腐涂装技能：精通环氧漆、聚氨酯漆、富锌底漆、沥青漆、聚脲、玻璃钢等各类防腐材料的施工工艺，熟练掌握刷涂、辊涂、喷涂等施工手法，精准控制涂层厚度、涂刷均匀度，熟练处理涂层流挂、起皮、气泡等常见问题。\\n3. 施工适配能力：熟练掌握钢结构、管道、储罐、混凝土、化工设备等不同基材的防腐施工要点，适配厂房、化工、市政、户外等各类施工场景，擅长高空作业、有限空间防腐施工。\\n4. 规范与安全：熟悉《建筑防腐蚀工程施工质量验收规范》《钢结构防腐涂装技术规程》等行业标准，掌握施工现场安全操作规程，熟知防腐施工危险品使用、防护及应急处理流程。\\n5. 工具设备：熟练操作喷砂设备、喷涂机、角磨机、打磨机、测厚仪等全套防腐施工及检测设备，可独立完成设备调试、操作与日常维护。\\n6. 综合素质：具备独立识图、领会施工方案、落实技术交底的能力，可独立完成单项防腐施工任务，服从现场管理，擅长团队协作，施工细致、责任心强。\",\"expectedPostId\":2020002,\"domicileAreaId\":610602,\"expectedCityAreaIds\":[610000],\"city\":\"陕西省\",\"postTypeId\":2020002,\"postTypeName\":\"防腐工\",\"expectedIndustry\":\"防腐保温\",\"company\":\"陕西防腐工程有限公司\",\"jobStart\":\"2021-08\",\"jobEnd\":\"2025-09\",\"workStart\":\"2021-08\",\"education\":\"大专\",\"school\":\"延安职业技术学校\",\"major\":\"建筑防腐与防水工程技术\",\"schoolType\":\"全日制\",\"educationStart\":\"2018-09\",\"educationEnd\":\"2021-07\",\"completedAt\":\"2026-09-16T03:13:26.701Z\"}','ee5f9bb5eb0dd5fcdeb7d9aa528b4abbfb2c210a2833f837ac51ec79f476c4c5','manual-3903e022-16c0-4d8e-85a7-202ccb95ed06',0,'81059','2026-09-18 14:40:13','81059','2026-09-18 14:40:13',_binary '\0',0),(2,81054,NULL,1,35,NULL,1,'手动固化 2026/9/18 14:45:01','v1','{\"name\":\"呵呵\",\"birthMonth\":\"2002-08\",\"mobile\":\"12389101234\",\"email\":\"3104757986@qq.com\",\"identity\":\"worker\",\"employmentStatus\":\"在职-月内到岗\",\"domicile\":\"陕西省 / 延安市\",\"strengths\":\"有丰富的的工作经验\",\"jobType\":\"fulltime\",\"expectedPostName\":\"预算员/造价员\",\"industry\":\"防腐保温\",\"salary\":\"all\",\"expectedCities\":[\"陕西省 / 延安市\"],\"experiences\":[{\"id\":\"1789436221373-n5vng7\",\"company\":\"天信管业有限公司\",\"industry\":\"\",\"department\":\"\",\"position\":\"\",\"start\":\"2024-10\",\"end\":\"2026-09\",\"description\":\"\",\"achievements\":\"\"}],\"projects\":[],\"educationExperiences\":[{\"id\":\"1789436221373-y0se6d\",\"degree\":\"本科\",\"school\":\"延安大学\",\"major\":\"材料科学与工程\",\"schoolType\":\"全日制\",\"start\":\"2020-09\",\"end\":\"2024-07\",\"experience\":\"\"}],\"skills\":\"办公软件、工程制图、项目管理、施工组织\",\"expectedPostId\":2020014,\"domicileAreaId\":610600,\"expectedCityAreaIds\":[610600],\"city\":\"陕西省 / 延安市\",\"postTypeId\":2020014,\"postTypeName\":\"预算员/造价员\",\"expectedIndustry\":\"防腐保温\",\"company\":\"天信管业有限公司\",\"jobStart\":\"2024-10\",\"jobEnd\":\"2026-09\",\"workStart\":\"2024-10\",\"education\":\"本科\",\"school\":\"延安大学\",\"major\":\"材料科学与工程\",\"schoolType\":\"全日制\",\"educationStart\":\"2020-09\",\"educationEnd\":\"2024-07\",\"completedAt\":\"2026-09-17T13:43:09.535Z\"}','67d6a84b9deea7cb0f8138ab0126b82cc8947a0f808a5144df4d5917598ade8c','manual-8ac36c24-002c-486e-9aa3-bd728091a9f0',0,'81054','2026-09-18 14:45:01','81054','2026-09-18 14:45:01',_binary '\0',0),(3,81052,NULL,1,19,NULL,1,'手动固化 2026/9/18 17:37:32','v1','{\"name\":\"drj123\",\"birthMonth\":\"2005-08\",\"mobile\":\"19289411644\",\"email\":\"3110740052@qq.com\",\"identity\":\"worker\",\"employmentStatus\":\"离职-随时到岗\",\"domicile\":\"上海\",\"strengths\":\"特别优秀\",\"jobType\":\"fulltime\",\"expectedPostName\":\"防腐工\",\"industry\":\"\",\"salary\":\"all\",\"expectedCities\":[\"榆林\"],\"experiences\":[],\"projects\":[],\"educationExperiences\":[{\"id\":\"1789368809197-tv30a2\",\"degree\":\"本科\",\"school\":\"清华大学\",\"major\":\"防腐保温相关专业\",\"schoolType\":\"全日制\",\"start\":\"2000-06\",\"end\":\"2004-06\",\"experience\":\"\"}],\"skills\":\"\",\"expectedPostId\":2020002,\"city\":\"榆林\",\"postTypeId\":2020002,\"postTypeName\":\"防腐工\",\"expectedIndustry\":\"\",\"company\":\"\",\"jobStart\":\"\",\"jobEnd\":\"