  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_candidate_version` (`candidate_id`,`version_no`),
  KEY `idx_candidate_id` (`candidate_id`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM å€™é€‰äººç®€åŽ†ç‰ˆæœ¬è¡¨';
