--
-- Table structure for table `hrm_salary_employee_info`
--

DROP TABLE IF EXISTS `hrm_salary_employee_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_salary_employee_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `change_reason` tinyint DEFAULT NULL COMMENT '定薪/调薪原因',
  `effect_time` datetime DEFAULT NULL COMMENT '生效时间',
  `change_type` tinyint DEFAULT '0' COMMENT '薪资状态',
  `probation_salary` decimal(12,2) DEFAULT '0.00' COMMENT '试用期工资',
  `regular_salary` decimal(12,2) DEFAULT '0.00' COMMENT '正式工资',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `salary_options` json DEFAULT NULL COMMENT '正式薪资项',
  `probation_salary_options` json DEFAULT NULL COMMENT '试用期薪资项',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_hrm_salary_employee_info_employee_id` (`employee_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4005 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工薪资信息表';
